package com.hbm.client.meteoritesword;
import com.hbm.client.model.LegacyItemTransforms;
import com.hbm.client.structureloot.LootPileRenderer;
import com.hbm.item.meteoritesword.MeteoriteSwordItem;
import com.mojang.blaze3d.vertex.*;
import com.mojang.math.Axis;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.*;
import net.minecraft.client.resources.model.ModelResourceLocation;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.*;
/** Exact source ItemRendererMeteorSword hand matrices,16px flat inventory and two bespoke colored glint passes; not ordinary foil. */
public final class MeteoriteSwordRenderer extends BlockEntityWithoutLevelRenderer {
 private static final ResourceLocation ICON=ResourceLocation.parse("hbm:textures/item/meteorite_sword.png");private static final ModelResourceLocation ORDINARY=ModelResourceLocation.standalone(ResourceLocation.parse("hbm:item/meteorite_sword_ordinary"));
 public MeteoriteSwordRenderer(){super(Minecraft.getInstance().getBlockEntityRenderDispatcher(),Minecraft.getInstance().getEntityModels());}
 private static void flush(MultiBufferSource buffers,RenderType type){if(buffers instanceof MultiBufferSource.BufferSource source)source.endBatch(type);}
 @Override public void renderByItem(ItemStack stack,ItemDisplayContext context,PoseStack pose,MultiBufferSource buffers,int light,int overlay){var sword=(MeteoriteSwordItem)stack.getItem();if(context==ItemDisplayContext.GROUND){var mc=Minecraft.getInstance();mc.getItemRenderer().render(stack,context,false,pose,buffers,light,overlay,mc.getModelManager().getModel(ORDINARY));return;}pose.pushPose();boolean gui=context==ItemDisplayContext.GUI;if(gui){pose.translate(0,1,.5);pose.scale(1F/16,-1F/16,1F/16);flat(pose,buffers,light,overlay,sword);}else{LegacyItemTransforms.heldFull3D(pose,context);if(context.firstPerson()){pose.mulPose(Axis.YP.rotationDegrees(180));pose.mulPose(Axis.ZP.rotationDegrees(-90));pose.translate(.5,.5,0);pose.translate(-.5,-.5,0);pose.mulPose(Axis.YP.rotationDegrees(180));pose.mulPose(Axis.ZP.rotationDegrees(-90));pose.translate(.5,.5,0);pose.scale(2.72F,2.72F,1.36F);pose.translate(-.5,-.5,.25);}else if(context==ItemDisplayContext.THIRD_PERSON_LEFT_HAND||context==ItemDisplayContext.THIRD_PERSON_RIGHT_HAND){pose.mulPose(Axis.YP.rotationDegrees(180));pose.mulPose(Axis.ZP.rotationDegrees(-90));pose.translate(.2,.55,0);pose.mulPose(Axis.ZP.rotationDegrees(45));pose.mulPose(Axis.YP.rotationDegrees(180));pose.mulPose(Axis.ZP.rotationDegrees(-45));pose.scale(1.7F,1.7F,.85F);}solid(pose,buffers,light,overlay,sword);}pose.popPose();}
 private static int color(MeteoriteSwordItem sword){return 0xff000000|((int)(sword.red*.36F*255)<<16)|((int)(sword.green*.36F*255)<<8)|(int)(sword.blue*.36F*255);}
 private static void flat(PoseStack pose,MultiBufferSource buffers,int light,int overlay,MeteoriteSwordItem sword){sourceFlatIcon(pose,buffers,light,overlay,ICON,color(sword),true);}
 public static void sourceFlatIcon(PoseStack pose,MultiBufferSource buffers,int light,int overlay,ResourceLocation icon,int tint,boolean foil){var base=RenderType.entityCutoutNoCull(icon);var out=buffers.getBuffer(base);quad(out,pose,new float[][]{{0,16,0,0,1},{16,16,0,1,1},{16,0,0,1,0},{0,0,0,0,0}},light,overlay,-1);flush(buffers,base);if(!foil)return;var type=MeteoriteSwordTypes.FLAT;for(int pass=0;pass<2;pass++){float period=3000+pass*1873,anim=(System.currentTimeMillis()%(long)period)/period*256F,mult=pass==0?4:-1;out=buffers.getBuffer(type);quad(out,pose,new float[][]{{0,16,0,(anim+16*mult)/256,16/256F},{16,16,0,(anim+16+16*mult)/256,16/256F},{16,0,0,(anim+16)/256,0},{0,0,0,anim/256,0}},light,overlay,tint);flush(buffers,type);}}
 private static void solid(PoseStack pose,MultiBufferSource buffers,int light,int overlay,MeteoriteSwordItem sword){var base=RenderType.entityCutoutNoCull(ICON);LootPileRenderer.extrude(1,0,0,1,16,16,.0625F,pose.last(),buffers.getBuffer(base),light,overlay,-1);flush(buffers,base);sourceSolidGlint(pose,buffers,overlay,color(sword));}
 public static void sourceSolidGlint(PoseStack pose,MultiBufferSource buffers,int overlay,int tint){var type=MeteoriteSwordTypes.SOLID;for(int pass=0;pass<2;pass++){float period=pass==0?3000:4873,offset=(System.currentTimeMillis()%(long)period)/period*8*(pass==0?1:-1),angle=(float)Math.toRadians(pass==0?-50:10),cos=(float)Math.cos(angle),sin=(float)Math.sin(angle);var out=uv(buffers.getBuffer(type),offset,cos,sin);LootPileRenderer.extrude(0,1,0,1,255,255,.0625F,pose.last(),out,LightTexture.FULL_BRIGHT,overlay,tint);flush(buffers,type);}}
 private static VertexConsumer uv(VertexConsumer out,float offset,float cos,float sin){return new VertexConsumer(){public VertexConsumer addVertex(float x,float y,float z){out.addVertex(x,y,z);return this;}public VertexConsumer setColor(int r,int g,int b,int a){out.setColor(r,g,b,a);return this;}public VertexConsumer setUv(float u,float v){out.setUv(.125F*(u*cos-v*sin+offset),.125F*(u*sin+v*cos));return this;}public VertexConsumer setUv1(int a,int b){return this;}public VertexConsumer setUv2(int a,int b){return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}};}
 private static void quad(VertexConsumer out,PoseStack pose,float[][] points,int light,int overlay,int color){for(var p:points)out.addVertex(pose.last(),p[0],p[1],p[2]).setColor(color).setUv(p[3],p[4]).setOverlay(overlay).setLight(light).setNormal(pose.last(),0,0,1);}
}
